css:
.fp { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .4rem 2rem; font-size: .9rem; color: var(--os-color-text-muted); }
.fp p { margin: 0; }
.fp a { color: var(--os-color-heading); }
.fp.is-row { width: min(100% - 2rem, var(--fp-w, 1180px)); margin: 2.5rem auto 0; padding: 1.5rem 0 2rem; border-top: 1px solid color-mix(in srgb, var(--os-color-text) 22%, transparent); }
